function scnPick(c,b,type){if(type=='tr')return 'transfer';if(type=='in')return 'income';const ico=scnIco(c);const sonst=!c||/^sonstig/i.test(String(c))||!ico||ico=='dot';
  if(sonst){if(type=='in')return 'income';if(b&&typeof sinkAcc=='function'&&b==sinkAcc())return 'chest';if(b&&typeof GN=='function'&&b==GN())return 'evening';if(!c||/^sonstig/i.test(String(c)))return 'city';}
  if(type=='in'&&!SCN_MAP[ico])return 'income';if(SCN_MAP[ico])return ico;let h=0;for(const ch of String(c||''))h=(h*31+ch.charCodeAt(0))>>>0;return ['city','hills','night'][h%3]}
function scnIco(c){if(!c)return null;for(const L of Object.values(S.cats||{})){const x=(L||[]).find(x=>x&&x[0]==c&&x[1]&&x[1]!='dot');if(x)return x[1]}return typeof iconFor=='function'?iconFor(c):null}
